type IconElementProps = {
  class?: string
  [key: string]: unknown
}

type IconProps = IconElementProps & {
  iconNode: IconNode
}

export const Icon: FC<IconProps> = ({
  iconNode,
  class: className,
  ...props
}) => (
  <svg
    xmlns='http://www.w3.org/2000/svg'
    width='24'
    height='24'
    viewBox='0 0 24 24'
    fill='none'
    stroke='currentColor'
    stroke-width='2'
